import { McpServer } from '@modelcontextprotocol/server';
import { StdioServerTransport } from '@modelcontextprotocol/server/stdio';
import { z } from 'zod';

const API_BASE_URL = process.env.API_BASE_URL ?? 'https://api.github.com';
const API_TOKEN = process.env.API_TOKEN ?? '';

function authHeaders(): Record<string, string> { return {}; }

const server = new McpServer({
  name: 'GitHub v3 REST API',
  version: '1.1.4',
});

server.registerTool(
  'meta_root',
  {
    description: 'GET / — Get Hypermedia links to resources accessible in GitHub\'s REST API',
    inputSchema: z.object({}),
  },
  async (args: Record<string, unknown>) => {
    const args_ = args;
    let url = API_BASE_URL + '/';
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      ...authHeaders(),
    };

    const fetchOpts: RequestInit = { method: 'GET', headers };

    try {
      const res = await fetch(url, fetchOpts);
      const text = await res.text();
      if (!res.ok) return { content: [{ type: 'text', text: JSON.stringify({ error: text }, null, 2) }] };
      try { return { content: [{ type: 'text', text: JSON.stringify(JSON.parse(text), null, 2) }] }; }
      catch { return { content: [{ type: 'text', text }] }; }
    } catch (err) {
      return { content: [{ type: 'text', text: JSON.stringify({ error: String(err) }) }] };
    }
  }
);

server.registerTool(
