    ghsa_id: z.optional(z.string()).describe('If specified, only advisories with this GHSA (GitHub Security Advisory) identifier will be returned.'),
    type: z.optional(z.string()).describe('If specified, only advisories of this type will be returned. By default, a request with no other parameters defined will only return reviewed advisories that are not malware.'),
    cve_id: z.optional(z.string()).describe('If specified, only advisories with this CVE (Common Vulnerabilities and Exposures) identifier will be returned.'),
    ecosystem: z.optional(z.string()).describe('If specified, only advisories for these ecosystems will be returned.'),
    severity: z.optional(z.string()).describe('If specified, only advisories with these severities will be returned.'),
