    is_withdrawn: z.optional(z.boolean()).describe('Whether to only return advisories that have been withdrawn.'),
    affects: z.optional(z.string()).describe('If specified, only return advisories that affect any of `package` or `package@version`. A maximum of 1000 packages can be specified.
If the query parameter causes the URL to exceed the maximum URL length supported by your client, you must specify fewer packages.

Example: `affects=package1,package2@1.0.0,package3@2.0.0` or `affects[]=package1&affects[]=package2@1.0.0`'),
    published: z.optional(z.string()).describe('If specified, only return advisories that were published on a date or date range.

For more information on the syntax of the date range, see "[Understanding the search syntax](https://docs.github.com/search-github/getting-started-with-searching-on-github/understanding-the-search-syntax#query-for-dates)."'),
    updated: z.optional(z.string()).describe('If specified, only return advisories that were updated on a date or date range.

