    sort: z.optional(z.string()).describe('The property to sort the results by.')
  }),
  },
  async (args: Record<string, unknown>) => {
    const {ghsa_id, type, cve_id, ecosystem, severity, cwes, is_withdrawn, affects, published, updated, modified, epss_percentage, epss_percentile, before, after, direction, per_page, sort} = args as {ghsa_id?: string, type?: string, cve_id?: string, ecosystem?: string, severity?: string, cwes?: string, is_withdrawn?: boolean, affects?: string, published?: string, updated?: string, modified?: string, epss_percentage?: string, epss_percentile?: string, before?: string, after?: string, direction?: string, per_page?: number, sort?: string};
    let url = API_BASE_URL + '/advisories';
