  if (published !== undefined) qs.append('published', String(published));
  if (updated !== undefined) qs.append('updated', String(updated));
  if (modified !== undefined) qs.append('modified', String(modified));
  if (epss_percentage !== undefined) qs.append('epss_percentage', String(epss_percentage));
  if (epss_percentile !== undefined) qs.append('epss_percentile', String(epss_percentile));
  if (before !== undefined) qs.append('before', String(before));
  if (after !== undefined) qs.append('after', String(after));
  if (direction !== undefined) qs.append('direction', String(direction));
  if (per_page !== undefined) qs.append('per_page', String(per_page));
  if (sort !== undefined) qs.append('sort', String(sort));
  const qstr = qs.toString();
  url += qstr ? '?' + qstr : '';
    const fetchOpts: RequestInit = { method: 'GET', headers };

    try {
      const res = await fetch(url, fetchOpts);
      const text = await res.text();
      if (!res.ok) return { content: [{ type: 'text', text: JSON.stringify({ error: text }, null, 2) }] };
