    let url = API_BASE_URL + '/repos/{owner}/{repo}/code-scanning/analyses/{analysis_id}'.replace('{owner}', encodeURIComponent(String(owner))).replace('{repo}', encodeURIComponent(String(repo))).replace('{analysis_id}', encodeURIComponent(String(analysis_id)));
